 27| /**
 28|  * Special implementation of the {@link UnivariateRealOptimizer} interface adding
 29|  * multi-start features to an existing optimizer.
 30|  * <p>
 31|  * This class wraps a classical optimizer to use it several times in
 32|  * turn with different starting points in order to avoid being trapped
 33|  * into a local extremum when looking for a global one.
 34|  * </p>
 35|  * @version $Revision$ $Date$
 36|  * @since 2.0
 37|  */
 38| public class MultiStartUnivariateRealOptimizer implements UnivariateRealOptimizer {
 39| 
 40|     /** Serializable version identifier. */
 41|     private static final long serialVersionUID = 5983375963110961019L;
 42| 
 43|     /** Underlying classical optimizer. */
 44|     private final UnivariateRealOptimizer optimizer;
 45| 
 46|     /** Maximal number of iterations allowed. */
 47|     private int maxIterations;
 48| 
 49|     /** Maximal number of evaluations allowed. */
 50|     private int maxEvaluations;
 51| 
 52|     /** Number of iterations already performed for all starts. */
 53|     private int totalIterations;
 54| 
 55|     /** Number of evaluations already performed for all starts. */
 56|     private int totalEvaluations;
 57| 
 58|     /** Number of starts to go. */
 59|     private int starts;
 60| 
 61|     /** Random generator for multi-start. */
 62|     private RandomGenerator generator;
 63| 
 64|     /** Found optima. */
 65|     private double[] optima;
 66| 
 67|     /** Found function values at optima. */
 68|     private double[] optimaValues;
 69| 
 70|     /**
 71|      * Create a multi-start optimizer from a single-start optimizer
 72|      * @param optimizer single-start optimizer to wrap
 73|      * @param starts number of starts to perform (including the
 74|      * first one), multi-start is disabled if value is less than or
 75|      * equal to 1
 76|      * @param generator random generator to use for restarts
 77|      */
 78|     public MultiStartUnivariateRealOptimizer(final UnivariateRealOptimizer optimizer,
 79|                                              final int starts,
 80|                                              final RandomGenerator generator) {
 81|         this.optimizer        = optimizer;
 82|         this.totalIterations  = 0;
 83|         this.starts           = starts;
 84|         this.generator        = generator;
 85|         this.optima           = null;
 86|         setMaximalIterationCount(Integer.MAX_VALUE);
 87|         setMaxEvaluations(Integer.MAX_VALUE);
 88|     }
