 25| /**
 26|  * Implements Richard Brent's algorithm (from his book "Algorithms for
 27|  * Minimization without Derivatives", p. 79) for finding minima of real
 28|  * univariate functions. This implementation is an adaptation partly
 29|  * based on the Python code from SciPy (module "optimize.py" v0.5).
 30|  *
 31|  * @version $Revision$ $Date$
 32|  * @since 2.0
 33|  */
 34| public class BrentOptimizer extends AbstractUnivariateRealOptimizer {
 35|     /**
 36|      * Golden section.
 37|      */
 38|     private static final double GOLDEN_SECTION = 0.5 * (3 - Math.sqrt(5));
 39| 
 40|     /**
 41|      * Construct a solver.
 42|      */
 43|     public BrentOptimizer() {
 44|         setMaxEvaluations(Integer.MAX_VALUE);
 45|         setMaximalIterationCount(100);
 46|         setAbsoluteAccuracy(1E-10);
 47|         setRelativeAccuracy(1.0e-14);
 48|     }
 49| 
 50|     /**
 51|      * Perform the optimization.
 52|      *
 53|      * @return the optimum.
 54|      */
 55|     protected double doOptimize()
 56|         throws MaxIterationsExceededException, FunctionEvaluationException {
 57|         throw new UnsupportedOperationException();
 58|     }
 59|     public double optimize(final UnivariateRealFunction f, final GoalType goalType, final double min, final double max, final double startValue) throws MaxIterationsExceededException, FunctionEvaluationException {
 60|         clearResult();
 61|         return localMin(getGoalType() == GoalType.MINIMIZE,
 62|                         f, goalType, min, startValue, max,
 63|                         getRelativeAccuracy(), getAbsoluteAccuracy());
 64|     }
 65|     public double optimize(final UnivariateRealFunction f, final GoalType goalType, final double min, final double max) throws MaxIterationsExceededException, FunctionEvaluationException {
 66|         return optimize(f, goalType, min, max, min + GOLDEN_SECTION * (max - min));
 67|     }
 68| 
 69|     /**
 70|      * Find the minimum of the function within the interval {@code (lo, hi)}.
 71|      *
 72|      * If the function is defined on the interval {@code (lo, hi)}, then
 73|      * this method finds an approximation {@code x} to the point at which
 74|      * the function attains its minimum.<br/>
 75|      * {@code t} and {@code eps} define a tolerance {@code tol = eps |x| + t}
 76|      * and the function is never evaluated at two points closer together than
 77|      * {@code tol}. {@code eps} should be no smaller than <em>2 macheps</em> and
 78|      * preferable not much less than <em>sqrt(macheps)</em>, where
 79|      * <em>macheps</em> is the relative machine precision. {@code t} should be
 80|      * positive.
 81|      * @param isMinim {@code true} when minimizing the function.
 82|      * @param lo Lower bound of the interval.
 83|      * @param mid Point inside the interval {@code [lo, hi]}.
 84|      * @param hi Higher bound of the interval.
 85|      * @param eps Relative accuracy.
 86|      * @param t Absolute accuracy.
 87|      * @return the optimum point.
 88|      * @throws MaxIterationsExceededException if the maximum iteration count
 89|      * is exceeded.
 90|      * @throws FunctionEvaluationException if an error occurs evaluating
 91|      * the function.
 92|      */
 93|     private double localMin(boolean isMinim,
 94|                             UnivariateRealFunction f,
 95|                             GoalType goalType,
 96|                             double lo, double mid, double hi,
 97|                             double eps, double t)
 98|         throws MaxIterationsExceededException, FunctionEvaluationException {
 99|         if (eps <= 0) {
100|             throw new NotStrictlyPositiveException(eps);
101|         }
102|         if (t <= 0) {
103|             throw new NotStrictlyPositiveException(t);
104|         }
105|         double a, b;
106|         if (lo < hi) {
107|             a = lo;
108|             b = hi;
109|         } else {
110|             a = hi;
111|             b = lo;
112|         }
113| 
114|         double x = mid;
115|         double v = x;
116|         double w = x;
117|         double d = 0;
118|         double e = 0;
119|         double fx = computeObjectiveValue(f, x);
120|         if (goalType == GoalType.MAXIMIZE) {
121|             fx = -fx;
122|         }
123|         double fv = fx;
124|         double fw = fx;
125| 
126|         int count = 0;
127|         while (count < maximalIterationCount) {
128|             double m = 0.5 * (a + b);
129|             final double tol1 = eps * Math.abs(x) + t;
130|             final double tol2 = 2 * tol1;
131| 
132|             // Check stopping criterion.
133|             if (Math.abs(x - m) > tol2 - 0.5 * (b - a)) {
134|                 double p = 0;
135|                 double q = 0;
136|                 double r = 0;
137|                 double u = 0;
138| 
139|                 if (Math.abs(e) > tol1) { // Fit parabola.
140|                     r = (x - w) * (fx - fv);
141|                     q = (x - v) * (fx - fw);
142|                     p = (x - v) * q - (x - w) * r;
143|                     q = 2 * (q - r);
144| 
145|                     if (q > 0) {
146|                         p = -p;
147|                     } else {
148|                         q = -q;
149|                     }
150| 
151|                     r = e;
152|                     e = d;
153| 
154|                     if (p > q * (a - x)
155|                         && p < q * (b - x)
156|                         && Math.abs(p) < Math.abs(0.5 * q * r)) {
157|                         // Parabolic interpolation step.
158|                         d = p / q;
159|                         u = x + d;
160| 
161|                         // f must not be evaluated too close to a or b.
162|                         if (u - a < tol2
163|                             || b - u < tol2) {
164|                             if (x <= m) {
165|                                 d = tol1;
166|                             } else {
167|                                 d = -tol1;
168|                             }
169|                         }
170|                     } else {
171|                         // Golden section step.
172|                         if (x < m) {
173|                             e = b - x;
174|                         } else {
175|                             e = a - x;
176|                         }
177|                         d = GOLDEN_SECTION * e;
178|                     }
179|                 } else {
180|                     // Golden section step.
181|                     if (x < m) {
182|                         e = b - x;
183|                     } else {
184|                         e = a - x;
185|                     }
186|                     d = GOLDEN_SECTION * e;
187|                 }
188| 
